add_filter( 'woocommerce_short_description', 'perfectpixel_default_short_description', 5 );

function perfectpixel_default_short_description( $excerpt ) {
	if ( '' !== trim( wp_strip_all_tags( (string) $excerpt ) ) || ! is_product() ) {
		return $excerpt;
	}
	return wp_kses_post( '{{default_short_description}}' );
}
